sp_widget.client_script:
api.controller = function($http, $window, spUtil) { 

    var c = this; 


    // ========================================= 
    // INITIAL VALUES 
    // ========================================= 

    c.email = ""; 
    c.password = ""; 
    c.message = ""; 
    c.isLoggingIn = false; 


    // ========================================= 
    // LOGIN 
    // ========================================= 

    c.login = function() { 

        if (c.isLoggingIn) { 
            return; 
        } 


        // ========================================= 
        // VALIDATE EMAIL 
        // ========================================= 

        if (!c.email) { 

            c.message = 
                "Please enter your college email address."; 

            return; 
        } 


        // ========================================= 
        // VALIDATE PASSWORD 
        // ========================================= 

        if (!c.password) { 

            c.message = 
                "Please enter your password."; 

            return; 
        } 


        c.message = ""; 
        c.isLoggingIn = true; 


        // ========================================= 
        // SERVICE NOW LOGIN URL 
        // ========================================= 

        var url = 
            spUtil.getURL({ 
                sysparm_type: "view_form.login" 
            }); 


        // ========================================= 
        // AUTHENTICATE 
        // ========================================= 

        $http({ 

            method: "post", 

            url: url, 

            data: $.param({ 

                sysparm_type: "login", 

                "ni.nolog.user_password": true, 

                remember_me: false, 

                user_name: c.email, 

                user_password: c.password, 

                get_redirect_url: true, 

                is_direct_redirect: true, 

                sysparm_goto_url: null, 

                mfa_redirect_url: null, 

                cert_login: false 

            }), 

            headers: { 
                "Content-Type": 
                    "application/x-www-form-urlencoded" 
            } 

        }).then(function(response) { 

            // ========================================= 
            // AUTHENTICATION RESPONSE 
            // ========================================= 

            if ( 
                response.data && 
                response.data.status === "success" 
            ) { 

                // ========================================= 
                // CHECK STUDENT PROFILE 
                // ========================================= 

                c.server.get({ 
                    action: "check_student" 
                }).then(function(studentResponse) { 

                    var result = studentResponse.data; 

                    // ========================================= 
                    // STUDENT PROFILE FOUND 
                    // ========================================= 

                    if (result.studentExists) { 

                        c.isLoggingIn = false; 
                        c.message = ""; 

                        $window.location.href = 
                            "?id=campus_connect_home"; 

                        return; 
                    } 


                    // ========================================= 
                    // STUDENT PROFILE NOT FOUND 
                    // ========================================= 

                    c.isLoggingIn = false; 
                    c.password = ""; 

                    c.message = 
                        result.message || 
                        "This account is not registered as a Campus Connect student."; 


                    // ========================================= 
                    // LOG OUT NON-STUDENT USER 
                    // ========================================= 

                    $http({ 
                        method: "get", 
                        url: "/logout.do" 
                    }).finally(function() { 

                        $window.location.href = 
                            "?id=campus_student_login"; 

                    }); 

                }, function() { 

                    c.isLoggingIn = false; 
                    c.password = ""; 

                    c.message = 
                        "Unable to verify your Campus Connect student profile."; 

                }); 

                return; 
            } 


            // ========================================= 
            // INVALID CREDENTIALS 
            // ========================================= 

            c.isLoggingIn = false; 
            c.password = ""; 

            c.message = 
                ( 
                    response.data && 
                    response.data.message 
                ) || 
                "Invalid email or password."; 


        }, function() { 

            c.isLoggingIn = false; 
            c.password = ""; 

            c.message = 
                "Unable to process your login request. Please try again."; 

        }); 

    }; 


    // ========================================= 
    // FORGOT PASSWORD 
    // ========================================= 

    c.forgotPassword = function() { 

        $window.location.href = 
            "$pwd_reset.do?sysparm_url=ss_default"; 

    }; 

};

sp_widget.css:
.student-login-page {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 40px 20px;

    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(37, 99, 235, 0.12),
            transparent 30%
        ),
        radial-gradient(
            circle at 85% 80%,
            rgba(30, 64, 175, 0.12),
            transparent 30%
        ),
        linear-gradient(
            135deg,
            #ffffff,
            #eff6ff,
            #dbeafe
        );

    font-family: Arial, sans-serif;
}


/* Login Card */

.login-card {
    width: 100%;
    max-width: 430px;

    padding: 40px;

    background: #ffffff;

    border-radius: 22px;

    box-shadow:
        0 20px 50px rgba(30, 64, 175, 0.15);

    border: 1px solid #bfdbfe;

    text-align: center;
}


/* Icon */

.login-icon {
    width: 70px;
    height: 70px;

    margin: 0 auto 20px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #dbeafe;

    color: #1d4ed8;

    font-size: 35px;

    box-shadow:
        0 8px 20px rgba(37, 99, 235, 0.12);
}


/* Heading */

.login-card h1 {
    margin: 0;

    font-size: 30px;

    font-weight: 800;

    color: #0f3d91;
}


/* Subtitle */

.login-subtitle {
    margin: 10px 0 30px;

    color: #475569;

    font-size: 14px;
}


/* Form */

.form-group {
    text-align: left;

    margin-bottom: 20px;
}


/* Labels */

.form-group label {
    display: block;

    margin-bottom: 8px;

    font-size: 14px;

    font-weight: 600;

    color: #1e3a8a;
}


/* Input */

.form-control {
    width: 100%;

    height: 48px;

    padding: 0 14px;

    border: 1px solid #bfdbfe;

    border-radius: 10px;

    background: #ffffff;

    color: #0f172a;

    font-size: 14px;

    box-sizing: border-box;

    outline: none;

    transition: 0.2s;
}


/* Input Placeholder */

.form-control::placeholder {
    color: #94a3b8;
}


/* Input Focus */

.form-control:focus {
    border-color: #2563eb;

    background: #ffffff;

    box-shadow:
        0 0 0 3px rgba(37, 99, 235, 0.12);
}


/* Login Button */

.login-submit {
    width: 100%;

    height: 50px;

    margin-top: 8px;

    border: none;

    border-radius: 10px;

    background: linear-gradient(
        135deg,
        #1d4ed8,
        #2563eb
    );

    color: #ffffff;

    font-size: 16px;

    font-weight: 700;

    cursor: pointer;

    transition: 0.25s;

    box-shadow:
        0 8px 20px rgba(37, 99, 235, 0.20);
}


/* Button Hover */

.login-submit:hover {
    transform: translateY(-2px);

    background: linear-gradient(
        135deg,
        #1e40af,
        #1d4ed8
    );

    box-shadow:
        0 10px 22px rgba(37, 99, 235, 0.30);
}


/* Button Active */

.login-submit:active {
    transform: translateY(0);
}


/* Links */

.login-links {
    margin-top: 25px;

    font-size: 13px;

    color: #64748b;
}


/* Link */

.login-links a {
    color: #2563eb;

    text-decoration: none;

    font-weight: 600;

    transition: 0.2s;
}


/* Link Hover */

.login-links a:hover {
    color: #1e40af;

    text-decoration: underline;
}


/* Mobile */

@media (max-width: 500px) {

    .student-login-page {
        padding: 20px 12px;
    }

    .login-card {
        padding: 30px 22px;
    }

    .login-card h1 {
        font-size: 26px;
    }
}

sp_widget.script:
(function() {

    data.studentExists = false;
    data.message = "";

    // =========================================
    // CHECK WHETHER LOGGED-IN USER IS A STUDENT
    // =========================================

    if (input && input.action === "check_student") {

        var userId = gs.getUserID();

        if (!userId) {
            data.studentExists = false;
            data.message = "User is not authenticated.";
            return;
        }

        // =========================================
        // CHECK STUDENT PROFILE
        // =========================================

        var studentProfile = new GlideRecord(
            "x_snc_campus_con_0_student_profile"
        );

        studentProfile.addQuery("student", userId);
        studentProfile.setLimit(1);
        studentProfile.query();

        if (studentProfile.next()) {

            data.studentExists = true;
            data.message = "Student profile found.";

        } else {

            data.studentExists = false;
            data.message =
                "This account is not registered as a Campus Connect student.";
        }

        return;
    }

})();
